type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // a.len() == r => treat as column vector, replicate each element across columns
    if a.len() == r {
        // For each row i, clone a[i] c times
        (0..r).map(|i| vec![a[i]; c]).collect()
    } else {
        // Otherwise a.len() == c, treat as row vector, replicate the whole row r times
        (0..r).map(|_| a.clone()).collect()
    }
}